import{Resend}from"resend";export default async function handler(req,res){if("POST"!==req.method)return res.status(405).json({error:"Method not allowed"});const{name:name,email:email,message:message,captcha:captcha}=req.body,captchaVerify=await fetch("https://www.google.com/recaptcha/api/siteverify",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:`secret=${process.env.RECAPTCHA_SECRET}&response=${captcha}`}),captchaData=await captchaVerify.json();if(!captchaData.success||captchaData.score<.5)return res.status(400).json({error:"Captcha validation failed"});const resend=new Resend(process.env.RESEND_API_KEY);try{await resend.emails.send({from:"Ken Portfolio <onboarding@resend.dev>",to:"ken54proweaver@gmail.com",subject:"New Contact Message",text:`Name: ${name}\nEmail: ${email}\nMessage: ${message}`}),res.status(200).json({message:"Success"})}catch(error){console.error(error),res.status(500).json({error:"Email failed to send"})}}